<?php
require dirname(__DIR__) . '/app/bootstrap.php';
$user = App\Auth::requireLogin();
$filters = [];
foreach (['q', 'year', 'status', 'requester', 'page'] as $key) $filters[$key] = is_string($_GET[$key] ?? null) ? $_GET[$key] : ($key === 'status' ? 'active' : '');
$result = App\Projects::search($filters);
$counts = array_fill_keys(array_keys(App\Projects::STATUSES), 0);
foreach (App\DB::query('SELECT status, COUNT(*) AS total FROM projects GROUP BY status')->fetchAll() as $row) $counts[$row['status']] = (int)$row['total'];
$years = App\DB::query('SELECT DISTINCT construction_year FROM projects ORDER BY construction_year DESC')->fetchAll(PDO::FETCH_COLUMN);
$requesters = App\DB::query('SELECT DISTINCT u.id, u.full_name, u.is_active FROM users u JOIN projects p ON p.requester_id=u.id ORDER BY u.full_name, u.id')->fetchAll();
$pageTitle = 'Projects';
require APP_ROOT . '/templates/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">LOCAL AGENCY PROJECTS</div><h1>Crash analysis</h1><p class="muted">From the first request to the final signature. Every project, in view.</p></div><?php if (in_array($user['role'], ['design','admin'], true)): ?><a class="button" href="<?= h(app_path('/request.php')) ?>"><span aria-hidden="true">＋</span> New request</a><?php endif; ?></div>
<?php if ($user['role'] === 'admin' && !App\ProjectContacts::ready()): ?><div class="alert warning">Select the two project contacts before submitting requests. <a href="<?= h(app_path('/admin/users.php#project-contacts')) ?>">Review accounts in People</a></div><?php endif; ?>
<div class="summary-strip" aria-label="Project totals"><?php foreach (App\Projects::STATUSES as $key => $label): ?><div class="summary-item"><span class="dot <?= h($key) ?>" aria-hidden="true"></span><strong><?= $counts[$key] ?></strong> <?= h($label) ?></div><?php endforeach; ?></div>
<section class="panel">
  <form method="get" class="filters" aria-label="Filter projects"><div class="search-field"><label for="q">FIND A PROJECT</label><input type="search" name="q" id="q" value="<?= h($filters['q']) ?>" maxlength="200" placeholder="Search project name, RCOC number, or MDOT job"></div><div><label for="status">STATUS</label><select name="status" id="status"><?php foreach (['active' => 'Active projects', 'all' => 'All projects'] + App\Projects::STATUSES as $key => $label): ?><option value="<?= h($key) ?>" <?= $filters['status'] === $key ? 'selected' : '' ?>><?= h($label) ?></option><?php endforeach; ?></select></div><div><label for="year">CONSTRUCTION YEAR</label><select name="year" id="year"><option value="">All years</option><?php foreach ($years as $year): ?><option value="<?= h($year) ?>" <?= (string)$year === $filters['year'] ? 'selected' : '' ?>><?= h($year) ?></option><?php endforeach; ?></select></div><div><label for="requester">REQUESTER</label><select name="requester" id="requester"><option value="">All requesters</option><?php foreach ($requesters as $requester): ?><option value="<?= (int)$requester['id'] ?>" <?= (string)$requester['id'] === $filters['requester'] ? 'selected' : '' ?>><?= h($requester['full_name']) ?><?= $requester['is_active'] ? '' : ' (inactive)' ?></option><?php endforeach; ?></select></div><button class="button secondary" type="submit">Filter</button><?php if ($filters['q'] || $filters['year'] || $filters['requester'] || $filters['status'] !== 'active'): ?><a class="filter-reset" href="<?= h(app_path('/dashboard.php')) ?>">Reset</a><?php endif; ?></form>
  <?php if (!$result['rows']): ?><div class="empty-state"><div class="empty-icon" aria-hidden="true">≡</div><h2><?= array_sum($counts) ? 'No projects match these filters' : 'Your next review starts here' ?></h2><p><?= array_sum($counts) ? 'Try another search or change the status, year, or requester filters.' : 'Submit a project to give Traffic Safety the details they need. You can follow each milestone here.' ?></p><?php if (!array_sum($counts) && in_array($user['role'], ['design','admin'], true)): ?><a class="button" href="<?= h(app_path('/request.php')) ?>">Create the first request</a><?php endif; ?></div>
  <?php else: ?><div class="table-scroll"><table class="projects-table"><thead><tr><th>Project</th><th class="requester-col">Requested by</th><th>Review progress &amp; deadline</th><th>Bid letting</th><th><span class="muted">Open</span></th></tr></thead><tbody><?php foreach ($result['rows'] as $project): ?><tr><td class="project-cell"><a class="project-name" href="<?= h(app_path('/project.php?id=' . $project['id'])) ?>"><?= h($project['name']) ?></a><span class="project-meta">RCOC <?= h($project['rcoc_number']) ?> <span aria-hidden="true">·</span> MDOT <?= h($project['mdot_number']) ?></span></td><td class="requester-col"><?= h($project['requester_name']) ?></td><td class="progress-cell"><div class="progress-deadline"><?php progress($project, true); ?><div class="deadline <?= App\Projects::overdue($project) ? 'overdue' : '' ?>"><small>Needed by</small><strong><?= h(local_date($project['needed_by'])) ?></strong><?php if (App\Projects::overdue($project)): ?><span class="due-flag">Overdue</span><?php elseif ($project['needed_by'] === today() && $project['status'] !== 'complete'): ?><span class="hint">Due today</span><?php endif; ?></div></div></td><td class="letting-col nowrap"><?= h(local_date($project['bid_date'])) ?></td><td class="link-col"><a class="row-link" href="<?= h(app_path('/project.php?id=' . $project['id'])) ?>" aria-label="Open <?= h($project['name']) ?>">↗</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
  <div class="table-footer"><span><?= $result['count'] ?> project<?= $result['count'] === 1 ? '' : 's' ?> · Earliest deadline first</span><?php if ($result['pages'] > 1): ?><nav class="pagination" aria-label="Project pages"><?php if ($result['page'] > 1): ?><a href="<?= h(app_path('/dashboard.php?' . http_build_query(array_merge($filters, ['page' => $result['page'] - 1])))) ?>">Previous</a><?php endif; ?><span><?= $result['page'] ?> / <?= $result['pages'] ?></span><?php if ($result['page'] < $result['pages']): ?><a href="<?= h(app_path('/dashboard.php?' . http_build_query(array_merge($filters, ['page' => $result['page'] + 1])))) ?>">Next</a><?php endif; ?></nav><?php endif; ?></div>
</section>
<p class="hint">Needed-by dates refer to the signed, completed analysis. Select a project to view its details and history.</p>
<?php require APP_ROOT . '/templates/footer.php'; ?>
